func topKFrequent(_ nums: [Int], _ k: Int) -> [Int] {
    var freq: [Int: Int] = [:]
    for n in nums { freq[n, default: 0] += 1 }
    var buckets = [[Int]](repeating: [], count: nums.count + 1)
    for (n, c) in freq { buckets[c].append(n) }
    var result: [Int] = []
    for c in stride(from: nums.count, through: 1, by: -1) {
        result += buckets[c]
        if result.count >= k { return Array(result.prefix(k)) }
    }
    return result
}
